/**
 * Client-side full-text search for Chaos theme.
 * Powered by pre-built offline inverted index generated by build_search_index.py.
 * Pure Vanilla JavaScript with zero third-party dependencies.
 */
(function () {
  'use strict';

  var dialog = document.getElementById('searchDialog');
  var input = document.getElementById('searchInput');
  var resultsContainer = document.getElementById('searchResults');
  var closeBtn = document.getElementById('searchClose');
  var toggleBtn = document.getElementById('searchToggle');

  if (!dialog || !input || !resultsContainer) {
    return;
  }

  var indexData = null;
  var isLoading = false;
  var selectedIndex = -1;
  var currentResults = [];
  var debounceTimer = null;
  var initialHTML = resultsContainer.innerHTML;
  var msgLoading = dialog.getAttribute('data-msg-loading') || 'Loading...';
  var msgEmpty = dialog.getAttribute('data-msg-empty') || 'No matching posts found';
  var msgError = dialog.getAttribute('data-msg-error') || 'Failed to load search index';

  function escapeHTML(str) {
    if (!str) return '';
    return String(str).replace(/[&<>'"]/g, function (tag) {
      var chars = { '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' };
      return chars[tag] || tag;
    });
  }

  function escapeRegExp(str) {
    return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }

  function loadIndex(callback) {
    if (indexData) {
      if (callback) callback();
      return;
    }
    if (isLoading) return;

    isLoading = true;
    resultsContainer.innerHTML = '<div class="search-loading">' + escapeHTML(msgLoading) + '</div>';

    var indexUrl = dialog.getAttribute('data-index-url') || '/search-index.json';
    fetch(indexUrl)
      .then(function (res) {
        if (!res.ok) {
          throw new Error('HTTP ' + res.status);
        }
        return res.json();
      })
      .then(function (data) {
        indexData = data;
        isLoading = false;
        resultsContainer.innerHTML = initialHTML;
        if (callback) callback();
      })
      .catch(function (err) {
        isLoading = false;
        resultsContainer.innerHTML = '<div class="search-error">' + escapeHTML(msgError) + ' (' + escapeHTML(err.message) + ')</div>';
      });
  }

  function openSearch() {
    dialog.showModal();
    input.focus();
    loadIndex(function () {
      if (input.value.trim()) {
        performSearch(input.value.trim());
      }
    });
  }

  function closeSearch() {
    dialog.close();
    input.value = '';
    resultsContainer.innerHTML = initialHTML;
    selectedIndex = -1;
    currentResults = [];
  }

  if (toggleBtn) {
    toggleBtn.addEventListener('click', function (e) {
      e.preventDefault();
      openSearch();
    });
  }

  if (closeBtn) {
    closeBtn.addEventListener('click', function () {
      closeSearch();
    });
  }

  // Close when clicking outside dialog content
  dialog.addEventListener('click', function (e) {
    var rect = dialog.getBoundingClientRect();
    var isInDialog =
      rect.top <= e.clientY &&
      e.clientY <= rect.top + rect.height &&
      rect.left <= e.clientX &&
      e.clientX <= rect.left + rect.width;
    if (!isInDialog || e.target === dialog) {
      closeSearch();
    }
  });

  // Global hotkey '/' to open search (unless typing in input/textarea)
  document.addEventListener('keydown', function (e) {
    if (e.key === '/' && !dialog.open) {
      var tag = (e.target && e.target.tagName) || '';
      if (tag !== 'INPUT' && tag !== 'TEXTAREA' && !e.target.isContentEditable) {
        e.preventDefault();
        openSearch();
      }
    } else if (e.key === 'Escape' && dialog.open) {
      closeSearch();
    }
  });

  // Query tokenization using inverted index dictionary
  function extractTokens(query) {
    var q = query.trim().toLowerCase();
    if (!q) return [];

    var tokens = [];
    // 1. Extract alphanumeric tokens
    var latinWords = q.match(/[a-z0-9_\-\.]+/gi) || [];
    latinWords.forEach(function (w) {
      if (w.length >= 1) tokens.push(w.toLowerCase());
    });

    // 2. Extract CJK phrases using dictionary matching against indexData.index keys
    var cjkChars = q.replace(/[a-z0-9_\-\.\s]+/gi, '');
    if (cjkChars && indexData && indexData.index) {
      var len = cjkChars.length;
      // Multi-gram forward matching (longest match)
      for (var i = 0; i < len; i++) {
        for (var l = Math.min(6, len - i); l >= 2; l--) {
          var sub = cjkChars.substr(i, l);
          if (indexData.index[sub]) {
            tokens.push(sub);
          }
        }
        // Also check single character
        var single = cjkChars.substr(i, 1);
        if (indexData.index[single]) {
          tokens.push(single);
        }
      }
    }

    // Deduplicate tokens
    var seen = {};
    return tokens.filter(function (t) {
      if (!t || seen[t]) return false;
      seen[t] = true;
      return true;
    });
  }

  function highlightText(text, tokens) {
    var escaped = escapeHTML(text);
    if (!tokens || tokens.length === 0) return escaped;

    var sortedTokens = tokens.slice().sort(function (a, b) {
      return b.length - a.length;
    });
    var pattern = '(' + sortedTokens.map(escapeRegExp).join('|') + ')';
    var re = new RegExp(pattern, 'gi');
    return escaped.replace(re, '<mark>$1</mark>');
  }

  function performSearch(query) {
    if (!indexData || !query.trim()) {
      resultsContainer.innerHTML = initialHTML;
      currentResults = [];
      selectedIndex = -1;
      return;
    }

    var tokens = extractTokens(query);
    if (tokens.length === 0) {
      // Fallback: match substring in titles directly
      tokens = [query.trim().toLowerCase()];
    }

    var scores = {};
    var docs = indexData.docs;
    var index = indexData.index;

    tokens.forEach(function (token) {
      var matchedDocIds = index[token];
      if (matchedDocIds) {
        matchedDocIds.forEach(function (id) {
          scores[id] = (scores[id] || 0) + 1;
        });
      } else {
        // Partial/prefix search for short latin query
        if (token.length >= 2) {
          for (var key in index) {
            if (key.indexOf(token) !== -1) {
              var ids = index[key];
              for (var j = 0; j < ids.length; j++) {
                scores[ids[j]] = (scores[ids[j]] || 0) + 0.5;
              }
            }
          }
        }
      }
    });

    // Score boosting for Title / Tags / Categories
    for (var idStr in scores) {
      var id = parseInt(idStr, 10);
      var doc = docs[id];
      if (!doc) continue;

      var titleLower = (doc.title || '').toLowerCase();
      var tagsLower = (doc.tags || []).join(' ').toLowerCase();

      tokens.forEach(function (token) {
        if (titleLower.indexOf(token) !== -1) {
          scores[id] += 15; // Heavy weight for title matches
        }
        if (tagsLower.indexOf(token) !== -1) {
          scores[id] += 8;  // Medium weight for tags
        }
      });
    }

    // Rank doc IDs
    var rankedIds = Object.keys(scores).map(function (k) {
      return parseInt(k, 10);
    });
    rankedIds.sort(function (a, b) {
      // 分数不同时按分数降序；分数相同时按 doc_id 升序（doc_id 越小发布时间越新）
      return (scores[b] - scores[a]) || (a - b);
    });

    currentResults = rankedIds.slice(0, 25).map(function (id) {
      return docs[id];
    });

    renderResults(currentResults, tokens);
  }

  function renderResults(results, tokens) {
    if (results.length === 0) {
      resultsContainer.innerHTML = '<div class="search-empty">' + escapeHTML(msgEmpty) + '</div>';
      selectedIndex = -1;
      return;
    }

    var html = '<ul class="search-list" role="listbox">';
    results.forEach(function (doc, idx) {
      var titleHighlighted = highlightText(doc.title, tokens);
      var summaryHighlighted = highlightText(doc.summary, tokens);
      var tagsHTML = '';
      if (doc.tags && doc.tags.length > 0) {
        tagsHTML = '<span class="search-item-tags">' +
          doc.tags.slice(0, 3).map(function (t) {
            return '<span class="search-tag">' + escapeHTML(t) + '</span>';
          }).join('') +
          '</span>';
      }

      html += '<li class="search-item" role="option" data-idx="' + idx + '" id="search-opt-' + idx + '">' +
        '<a href="' + escapeHTML(doc.url) + '" class="search-item-link">' +
          '<div class="search-item-header">' +
            '<span class="search-item-title">' + titleHighlighted + '</span>' +
            '<span class="search-item-date">' + escapeHTML(doc.date) + '</span>' +
          '</div>' +
          (summaryHighlighted ? '<div class="search-item-summary">' + summaryHighlighted + '</div>' : '') +
          tagsHTML +
        '</a>' +
      '</li>';
    });
    html += '</ul>';

    resultsContainer.innerHTML = html;
    selectedIndex = -1;
  }

  function updateSelection(newIdx) {
    var items = resultsContainer.querySelectorAll('.search-item');
    if (items.length === 0) return;

    if (selectedIndex >= 0 && items[selectedIndex]) {
      items[selectedIndex].classList.remove('is-selected');
      items[selectedIndex].removeAttribute('aria-selected');
    }

    selectedIndex = newIdx;
    if (selectedIndex < 0) selectedIndex = items.length - 1;
    if (selectedIndex >= items.length) selectedIndex = 0;

    var currentItem = items[selectedIndex];
    if (currentItem) {
      currentItem.classList.add('is-selected');
      currentItem.setAttribute('aria-selected', 'true');
      currentItem.scrollIntoView({ block: 'nearest' });
    }
  }

  // Keyboard navigation inside search input
  input.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      updateSelection(selectedIndex + 1);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      updateSelection(selectedIndex - 1);
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (selectedIndex >= 0 && currentResults[selectedIndex]) {
        window.location.href = currentResults[selectedIndex].url;
      } else if (currentResults.length > 0) {
        window.location.href = currentResults[0].url;
      }
    }
  });

  // Debounced input search
  input.addEventListener('input', function () {
    clearTimeout(debounceTimer);
    debounceTimer = setTimeout(function () {
      performSearch(input.value);
    }, 150);
  });
})();
